async function queryNode(ip) {
  try {
    const res = await fetch(`http://${ip}/health`, { signal: AbortSignal.timeout(3000) });
    if (!res.ok) throw new Error(`HTTP error: ${res.status}`);
    const data = await res.json();
    return { ip, status: 'OK', data };
  } catch (err) {
    console.error(`Failed ${ip}: ${err.message}`);
    return { ip, status: 'FAILED', error: err.message };
  }
}

// Concurrent parallel execution across multiple nodes
const results = await Promise.all(['10.0.0.1', '10.0.0.2'].map(queryNode));

