function Test-NodeConnection {
  [CmdletBinding()]
  param(
    [Parameter(Mandatory = $true, ValueFromPipeline = $true)]
    [string]$ComputerName,
    [int]$TimeoutSeconds = 5
  )
  process {
    $ErrorActionPreference = 'Stop'
    try {
      $res = Test-Connection -TargetName $ComputerName -Count 1 -TimeoutSeconds $TimeoutSeconds
      [PSCustomObject]@{ Computer = $ComputerName; Status = 'ONLINE'; Latency = $res.Latency }
    } catch {
      Write-Error "Failed to reach $ComputerName: $_"
      [PSCustomObject]@{ Computer = $ComputerName; Status = 'OFFLINE'; Latency = $null }
    }
  }
}

